#!/usr/bin/env ruby

require 'json'
require 'nokogiri'

# Finance golden test for variaveis.tjp (Phase 8.8)
# Generates golden JSON from the 8 taskreports generated by tj3.
#
# Each report isolates one variation:
#   report-100pct  — chargeset 100% dev
#   report-70-30   — chargeset 70/30 dev/mat
#   report-50-50   — chargeset 50/50 dev/mat
#   report-null    — purge chargeset (zero cost)
#   report-charges — charge onStart/onEnd/perDiem
#   report-credit  — charge on revenue account
#   report-balance  — balance rev cost (reversed order)
#   report-perhour  — charge perhour
#
# Usage: ruby scripts/golden/finance-variations.rb

OUTPUT_FILE = File.expand_path("../../packages/core/tests/golden/finance-variations.golden.json", __dir__)
TJP_PATH = File.expand_path("../../docs/Learning/mwe004/variaveis.tjp", __dir__)
OUTPUT_DIR = File.expand_path("../../packages/core/tests/golden", __dir__)

$stderr.puts "Running tj3 on mwe004/variaveis.tjp..."
Dir.mkdir(OUTPUT_DIR, 0755) rescue nil

result = system("cd #{File.dirname(TJP_PATH)} && tj3 #{TJP_PATH} -o #{OUTPUT_DIR}")
if !result
  $stderr.puts "ERROR: tj3 failed to generate reports"
  exit 1
end

# TJ uses European number formatting: comma as decimal, dot as thousands.
# e.g. "36526,25" = 36526.25, "21000,00" = 21000.00
def parse_number(text)
  return 0.0 if text.nil? || text.strip.empty?
  cleaned = text.gsub(/[^\d,.\-]/, "").gsub(".", "").tr(",", ".")
  cleaned.to_f
end

# Parse TJ effort strings like "4.0d" (days), "5.3d" (days) into numeric days.
def parse_effort(text)
  return 0.0 if text.nil? || text.strip.empty?
  cleaned = text.strip
  if cleaned =~ /^([\d\.]+)([wdmhy])?$/
    value = $1.to_f
    unit = $2 || "d"
    case unit
    when "d" then value
    when "w" then value * 7.0
    when "m" then value * 30.0
    when "h" then value / 8.0
    else value
    end
  else
    0.0
  end
end

# Map report file name to a scenario description and its task ID prefix.
# Each taskreport shows the entire project tree, so we filter to only the
# tasks belonging to the scenario by matching the task ID prefix.
REPORT_SCENARIOS = {
  "report-100pct" => ["chargeset 100% dev",        "t1_100pct"],
  "report-70-30"  => ["chargeset 70-30 dev/mat",   "t2_split"],
  "report-50-50"  => ["chargeset 50-50 dev/mat",   "t7_split50"],
  "report-null"   => ["purge chargeset",           "t3_purge"],
  "report-charges" => ["charge onStart/onEnd/perDiem", "t4_charges"],
  "report-credit" => ["charge on revenue account", "t5_credit"],
  "report-balance" => ["balance rev cost (reversed)", "t6_balance"],
  "report-perhour" => ["charge perhour",           "t8_perhour"]
}

# Extract task rows from a taskreport HTML, filtered by scenario task ID prefix.
# Each <tr class="tabline"> has 4 <td> cells:
#   [0] Name, [1] Effort, [2] Cost, [3] Revenue
# The task ID is in the tooltip box: <b>ID:</b> t1_100pct.spec
def parse_taskreport(path, id_prefix)
  doc = Nokogiri::HTML(File.read(path))
  cases = []

  doc.xpath('//table[@class="tj_table"]//tr[@class="tabline"]').each do |row|
    cells = row.xpath('./td')
    next if cells.length < 4

    name_cell = cells[0].xpath('.//td[@class="tj_table_cell_label"]').last
    next if name_cell.nil?
    name = name_cell.text.strip
    next if name.empty?

    # Get the task ID from the tooltip box
    tooltip = cells[0].xpath('.//div[@class="tj_tooltip_box"]//b[text()="ID:"]/following-sibling::text()')
    task_id = tooltip.first&.text&.strip || ""

    # Filter: only tasks belonging to this scenario
    next unless task_id.start_with?(id_prefix)

    effort = parse_number(cells[1].xpath('.//td[@class="tj_table_cell_label"]').last.text)
    cost = parse_number(cells[2].xpath('.//td[@class="tj_table_cell_label"]').last.text)
    revenue = parse_number(cells[3].xpath('.//td[@class="tj_table_cell_label"]').last.text)

    cases << {
      "description" => name,
      "method" => "to_tjp",
      "type" => "Task",
      "input" => { "value" => nil },
      "expected" => {
        "effort" => effort,
        "cost" => cost,
        "revenue" => revenue,
        "balance" => revenue - cost,
        "turnover" => cost + revenue
      }
    }
  end
  cases
end

cases = []
REPORT_SCENARIOS.each do |report_name, (scenario, id_prefix)|
  report_path = File.join(OUTPUT_DIR, "#{report_name}.html")
  next unless File.exist?(report_path)

  report_cases = parse_taskreport(report_path, id_prefix)
  report_cases.each do |c|
    c["description"] = "[#{scenario}] #{c["description"]}"
  end
  cases.concat(report_cases)
end

# Create golden JSON structure
# (sem `generated_at` — timestamp de wall-clock quebraria a idempotência do golden)
golden = {
  "version" => "1.0",
  "description" => "Casos financeiros extraidos de mwe004/variaveis.tjp (8 taskreports isolando variacoes de chargeset, charge modes, credit, balance order)",
  "cases" => cases
}

# Output JSON to stdout for capture by generate_golden.ts
# (log messages go to stderr so they don't pollute the JSON output)
$stderr.puts "Generated #{OUTPUT_FILE} with #{cases.length} cases"
$stderr.puts "Tasks: #{cases.select { |c| c["type"] == "Task" }.length}"
puts JSON.pretty_generate(golden)